/*
 * Tendora workbench UI.
 * No build step. No dependencies. No network beyond the local workbench API.
 */
(function () {
  'use strict';

  var E = window.TendoraEngine;
  var STORAGE_KEY = 'tendora.workbench.v1';
  var SOUND_KEY = 'tendora.sound.v1';
  var SVG_NS = 'http://www.w3.org/2000/svg';

  var KIND_LABELS = {
    memory: 'INHERITED MEMORY',
    kindle: 'FIRST LIGHT',
    probe: 'PROBE',
    chisel: 'CHISEL',
    beam: 'BEAM',
    boundary: 'BOUNDARY',
    rehearsal: 'REHEARSE'
  };

  var KIND_COLORS = {
    memory: '#8b877d',
    kindle: '#db9d62',
    probe: '#7bd7c9',
    chisel: '#db9d62',
    beam: '#efe6d1',
    boundary: '#a99be8',
    rehearsal: '#d98694'
  };

  var state = null;
  var selectedSeq = null;
  var selectedTool = 'probe';
  var serverReachable = false;
  var saveTimer = null;
  var saveInFlight = false;
  var saveQueued = false;
  var saveFailureNotified = false;
  var toastTimer = null;
  var soundOn = false;
  var audioContext = null;
  var newSeq = null;
  var els = {};

  function byId(id) {
    return document.getElementById(id);
  }

  function cacheElements() {
    [
      'saveBadge', 'saveLabel', 'soundButton', 'soundLabel', 'memoryButton', 'memoryLink',
      'protocolButton', 'worldTitle', 'worldQuestion', 'revisionLabel', 'pulseWord', 'facets',
      'inheritanceNote', 'fieldCount', 'weather', 'worldSvg', 'worldSvgDesc', 'worldScene',
      'answerCard', 'answerMeta', 'answerStamp', 'answerCopy', 'answerPressure', 'answerPressureText',
      'receiptList', 'receiptCount', 'tensionList', 'tensionCount', 'doorButton', 'archiveState',
      'gestureForm', 'gestureInput', 'charCount', 'placeButton', 'placeButtonLabel', 'toolCue',
      'memoryDialog', 'protocolDialog', 'doorDialog', 'protocolSaveStatus', 'doorText', 'doorSaveNote',
      'copyHandoffButton', 'downloadHandoffButton', 'downloadWorldButton', 'exportButton',
      'importButton', 'importInput', 'resetButton', 'toast'
    ].forEach(function (id) {
      els[id] = byId(id);
    });
  }

  function init() {
    cacheElements();
    if (!E) {
      els.answerCopy.textContent = 'The workbench engine did not load. Read world/state.json directly, or run the test suite.';
      els.answerMeta.textContent = 'ENGINE MISSING';
      return;
    }

    bindEvents();
    setTool('probe');
    initSound();

    loadWorld().then(function (loaded) {
      state = loaded.world;
      selectedSeq = state.receipts[state.receipts.length - 1].seq;
      renderAll(null);
      if (loaded.source === 'workbench') {
        setSaveStatus('ready', 'saved to disk');
      } else if (loaded.source === 'browser') {
        setSaveStatus('local', 'browser only');
      } else if (loaded.source === 'inherited') {
        setSaveStatus('local', 'filesystem copy');
      } else {
        setSaveStatus(serverReachable ? 'ready' : 'local', serverReachable ? 'saved to disk' : 'browser only');
      }
      if (loaded.needsPush && serverReachable) {
        queueServerSave(50);
      }
      if (loaded.warning) {
        showToast(loaded.warning, 'error');
      }
    }).catch(function (error) {
      console.error(error);
      state = E.createLocalWorld(new Date().toISOString());
      selectedSeq = state.receipts[state.receipts.length - 1].seq;
      renderAll(null);
      setSaveStatus('error', 'browser only');
      showToast('The workbench opened from a local seed. The archive could not be read.', 'error');
    });
  }

  /* ------------------------------------------------------------
     Persistence
     ------------------------------------------------------------ */

  function readLocalWorld() {
    try {
      var raw = window.localStorage.getItem(STORAGE_KEY);
      if (!raw) {
        return null;
      }
      var parsed = JSON.parse(raw);
      var validated = E.validateWorld(parsed);
      if (!validated.ok) {
        window.localStorage.removeItem(STORAGE_KEY);
        return null;
      }
      return parsed;
    } catch (error) {
      return null;
    }
  }

  function writeLocalWorld() {
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (error) {
      showToast('This browser could not store the world. Export it before closing.', 'error');
    }
  }

  async function readRemoteWorld() {
    if (window.location.protocol === 'file:') {
      return { world: null, reachable: false, warning: '' };
    }
    var controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    var timer = controller ? window.setTimeout(function () { controller.abort(); }, 2200) : null;
    try {
      var response = await fetch('api/world', {
        method: 'GET',
        cache: 'no-store',
        headers: { 'Accept': 'application/json' },
        signal: controller ? controller.signal : undefined
      });
      if (!response.ok) {
        return { world: null, reachable: false, warning: '' };
      }
      var parsed = await response.json();
      var validated = E.validateWorld(parsed);
      if (!validated.ok) {
        return {
          world: null,
          reachable: true,
          warning: 'The workbench state on disk is invalid: ' + validated.errors[0]
        };
      }
      return { world: parsed, reachable: true, warning: '' };
    } catch (error) {
      return { world: null, reachable: false, warning: '' };
    } finally {
      if (timer) {
        window.clearTimeout(timer);
      }
    }
  }

  async function loadWorld() {
    var local = readLocalWorld();
    var remote = await readRemoteWorld();
    serverReachable = remote.reachable;

    if (remote.world && local) {
      var localIsNewer = local.revision > remote.world.revision ||
        (local.revision === remote.world.revision && String(local.updatedAt) > String(remote.world.updatedAt));
      if (localIsNewer) {
        writeLocalWorldFor(local);
        return { world: local, source: 'browser', needsPush: true, warning: remote.warning };
      }
      writeLocalWorldFor(remote.world);
      return { world: remote.world, source: 'workbench', needsPush: false, warning: remote.warning };
    }

    if (remote.world) {
      writeLocalWorldFor(remote.world);
      return { world: remote.world, source: 'workbench', needsPush: false, warning: remote.warning };
    }

    if (local) {
      return { world: local, source: 'browser', needsPush: serverReachable, warning: remote.warning };
    }

    var inherited = inheritedSnapshot();
    if (inherited) {
      writeLocalWorldFor(inherited);
      return { world: inherited, source: 'inherited', needsPush: false, warning: remote.warning };
    }

    var seed = E.createLocalWorld(new Date().toISOString());
    writeLocalWorldFor(seed);
    return { world: seed, source: 'seed', needsPush: serverReachable, warning: remote.warning };
  }

  function inheritedSnapshot() {
    var candidate = window.TENDORA_INHERITED_STATE;
    if (!candidate) {
      return null;
    }
    var validated = E.validateWorld(candidate);
    return validated.ok ? candidate : null;
  }

  function writeLocalWorldFor(world) {
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(world));
    } catch (error) {
      // The caller surfaces storage failures when the first gesture is made.
    }
  }

  function queueServerSave(delay) {
    if (!serverReachable) {
      setSaveStatus('local', 'browser only');
      return;
    }
    if (saveTimer) {
      window.clearTimeout(saveTimer);
    }
    saveTimer = window.setTimeout(function () {
      saveTimer = null;
      flushServerSave();
    }, typeof delay === 'number' ? delay : 160);
  }

  async function flushServerSave() {
    if (!serverReachable || !state) {
      return;
    }
    if (saveInFlight) {
      saveQueued = true;
      return;
    }
    saveInFlight = true;
    saveQueued = false;
    setSaveStatus('saving', 'writing to disk…');
    var sentRevision = state.revision;
    try {
      var response = await fetch('api/world', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify(state)
      });
      if (!response.ok) {
        throw new Error('The workbench rejected the save.');
      }
      saveFailureNotified = false;
      if (state.revision !== sentRevision) {
        saveQueued = true;
      }
      setSaveStatus('ready', 'saved to disk');
    } catch (error) {
      serverReachable = false;
      setSaveStatus('error', 'browser only');
      if (!saveFailureNotified) {
        saveFailureNotified = true;
        showToast('The disk copy is out of reach. This world is still safe in this browser.', 'error');
      }
    } finally {
      saveInFlight = false;
      if (saveQueued && serverReachable) {
        queueServerSave(80);
      }
    }
  }

  function setSaveStatus(kind, label) {
    if (els.saveBadge) {
      els.saveBadge.dataset.state = kind;
      els.saveBadge.title = {
        ready: 'Saved to world/state.json and this browser.',
        saving: 'Writing the current world to world/state.json.',
        local: 'Stored in this browser only. Run ./serve for a disk copy.',
        error: 'The disk copy is unavailable. The browser copy remains.'
      }[kind] || '';
    }
    if (els.saveLabel) {
      els.saveLabel.textContent = label;
    }
    var archiveText = kind === 'ready' ? 'workbench + browser' : (kind === 'saving' ? 'writing…' : 'browser only');
    if (els.archiveState) {
      els.archiveState.textContent = archiveText;
    }
    if (els.protocolSaveStatus) {
      els.protocolSaveStatus.textContent = kind === 'ready'
        ? 'Living archive: world/state.json + this browser.'
        : 'Living archive: this browser only. Export the world for a filesystem trail.';
    }
    if (els.doorSaveNote) {
      els.doorSaveNote.textContent = kind === 'ready'
        ? 'Also saved to world/state.json. The door is not only this export.'
        : 'This copy lives in the browser. Download the world to leave a filesystem trail.';
    }
  }

  function flushOnPageHide() {
    if (!serverReachable || !state) {
      return;
    }
    try {
      fetch('api/world', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(state),
        keepalive: true
      });
    } catch (error) {
      // The browser or server may already be gone. The local copy remains.
    }
  }

  /* ------------------------------------------------------------
     Rendering: text and ledger
     ------------------------------------------------------------ */

  function renderAll(animateSeq) {
    if (!state) {
      return;
    }
    document.title = state.title + ' · Tendora';
    document.body.dataset.phase = state.phase || 'awake';
    els.worldTitle.textContent = state.title;
    els.worldQuestion.textContent = '“' + state.question + '”';
    els.revisionLabel.textContent = pad(state.revision);
    els.inheritanceNote.textContent = state.inheritance.note;
    els.pulseWord.textContent = E.pulseWord(state);
    els.weather.textContent = E.weatherFor(state);
    var open = E.openTensions(state);
    els.fieldCount.textContent = state.receipts.length + ' receipts · ' + open.length + ' pressures';
    renderFacets();
    renderReceipts();
    renderTensions();
    renderAnswer();
    renderField(animateSeq);
    if (animateSeq !== null && animateSeq !== undefined) {
      els.receiptList.scrollTop = 0;
      els.tensionList.scrollTop = 0;
    }
  }

  function renderFacets() {
    var rows = els.facets.querySelectorAll('.facet');
    for (var i = 0; i < rows.length; i += 1) {
      var row = rows[i];
      var key = row.getAttribute('data-facet');
      var value = state.facets[key];
      row.querySelector('i').style.width = value + '%';
      row.querySelector('.facet-value').textContent = value;
      row.querySelector('.facet-track').setAttribute('aria-valuenow', value);
    }
  }

  function renderReceipts() {
    var previousScroll = els.receiptList.scrollTop;
    els.receiptList.textContent = '';
    els.receiptCount.textContent = pad(state.receipts.length);
    var reversed = state.receipts.slice().reverse();
    var fragment = document.createDocumentFragment();

    reversed.forEach(function (receipt) {
      var item = document.createElement('li');
      var button = document.createElement('button');
      button.type = 'button';
      button.className = 'receipt' + (receipt.seq === selectedSeq ? ' is-active' : '');
      button.setAttribute('data-kind', receipt.kind);
      button.setAttribute('aria-label', 'Receipt ' + receipt.seq + ', ' + (KIND_LABELS[receipt.kind] || receipt.kind) + ': ' + receipt.text);
      if (receipt.seq === selectedSeq) {
        button.setAttribute('aria-current', 'true');
      }

      var index = document.createElement('span');
      index.className = 'receipt-index';
      index.textContent = pad(receipt.seq);

      var body = document.createElement('span');
      body.className = 'receipt-body';
      var kind = document.createElement('span');
      kind.className = 'receipt-kind';
      kind.textContent = KIND_LABELS[receipt.kind] || receipt.kind.toUpperCase();
      var text = document.createElement('span');
      text.className = 'receipt-text';
      text.textContent = receipt.text;
      body.appendChild(kind);
      body.appendChild(text);

      var fp = document.createElement('span');
      fp.className = 'receipt-fp';
      fp.textContent = E.shortFingerprint(receipt.fingerprint);
      fp.title = 'FNV-1a chain fingerprint: ' + receipt.fingerprint;

      button.appendChild(index);
      button.appendChild(body);
      button.appendChild(fp);
      button.addEventListener('click', function () {
        selectReceipt(receipt.seq);
      });
      item.appendChild(button);
      fragment.appendChild(item);
    });

    if (!reversed.length) {
      var empty = document.createElement('li');
      empty.className = 'empty-state';
      empty.textContent = 'The ledger is empty. The material is still waiting.';
      fragment.appendChild(empty);
    }
    els.receiptList.appendChild(fragment);
    els.receiptList.scrollTop = previousScroll;
  }

  function renderTensions() {
    els.tensionList.textContent = '';
    var open = E.openTensions(state).slice().reverse();
    els.tensionCount.textContent = pad(open.length);
    var fragment = document.createDocumentFragment();

    open.forEach(function (tension) {
      var item = document.createElement('li');
      item.className = 'tension-item';

      var text = document.createElement('button');
      text.type = 'button';
      text.className = 'tension-text';
      text.textContent = tension.text;
      text.title = 'Show receipt #' + pad(tension.from);
      text.addEventListener('click', function () {
        selectReceipt(tension.from);
      });

      var take = document.createElement('button');
      take.type = 'button';
      take.className = 'tension-take';
      take.textContent = 'take up';
      take.setAttribute('aria-label', 'Take up this pressure: ' + tension.text);
      take.addEventListener('click', function () {
        takeUpPressure(tension);
      });

      item.appendChild(text);
      item.appendChild(take);
      fragment.appendChild(item);
    });

    if (!open.length) {
      var empty = document.createElement('li');
      empty.className = 'tension-empty';
      empty.textContent = 'No open pressures. The world is holding its breath.';
      fragment.appendChild(empty);
    }
    els.tensionList.appendChild(fragment);
  }

  function renderAnswer() {
    if (!state || !state.receipts.length) {
      return;
    }
    var receipt = receiptBySeq(selectedSeq) || state.receipts[state.receipts.length - 1];
    var lastSeq = state.receipts[state.receipts.length - 1].seq;
    els.answerMeta.textContent = (KIND_LABELS[receipt.kind] || receipt.kind.toUpperCase()) +
      ' · RECEIPT ' + pad(receipt.seq) + (receipt.seq === lastSeq ? '' : ' · FROM LEDGER');
    els.answerStamp.textContent = formatWhen(receipt.at);
    els.answerStamp.title = 'Fingerprint ' + receipt.fingerprint;
    els.answerCopy.textContent = receipt.response;
    els.answerCard.style.setProperty('--answer-accent', KIND_COLORS[receipt.kind] || 'var(--copper)');

    if (receipt.pressure) {
      els.answerPressure.hidden = false;
      els.answerPressureText.textContent = receipt.pressure;
    } else {
      els.answerPressure.hidden = true;
      els.answerPressureText.textContent = '';
    }

    els.answerCard.classList.remove('is-changing');
    void els.answerCard.offsetWidth;
    els.answerCard.classList.add('is-changing');
  }

  function receiptBySeq(seq) {
    if (!state || seq === null || seq === undefined) {
      return null;
    }
    for (var i = 0; i < state.receipts.length; i += 1) {
      if (state.receipts[i].seq === seq) {
        return state.receipts[i];
      }
    }
    return null;
  }

  function selectReceipt(seq) {
    if (!receiptBySeq(seq)) {
      return;
    }
    selectedSeq = seq;
    renderReceipts();
    renderAnswer();
    renderField(null);
  }

  function takeUpPressure(tension) {
    if (!tension) {
      return;
    }
    setTool('probe');
    els.gestureInput.value = tension.text;
    updateInputState();
    els.gestureInput.focus();
    els.gestureInput.setSelectionRange(els.gestureInput.value.length, els.gestureInput.value.length);
    showToast('Pressure taken into the probe. Change it before placing it.');
  }

  function pad(value) {
    return String(value).padStart(2, '0');
  }

  function formatWhen(iso) {
    var date = new Date(iso);
    if (isNaN(date.getTime())) {
      return String(iso || '');
    }
    var datePart = date.toLocaleDateString('en-GB', {
      day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC'
    }).toUpperCase();
    var timePart = date.toLocaleTimeString('en-GB', {
      hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'UTC'
    });
    return datePart + ' · ' + timePart + ' UTC';
  }

  /* ------------------------------------------------------------
     Gesture handling
     ------------------------------------------------------------ */

  function setTool(kind) {
    if (!E.TOOLS[kind]) {
      return;
    }
    selectedTool = kind;
    var buttons = document.querySelectorAll('.tool');
    for (var i = 0; i < buttons.length; i += 1) {
      var isActive = buttons[i].getAttribute('data-tool') === kind;
      buttons[i].classList.toggle('is-active', isActive);
      buttons[i].setAttribute('aria-pressed', isActive ? 'true' : 'false');
    }
    var tool = E.TOOLS[kind];
    els.gestureInput.placeholder = tool.placeholder;
    els.gestureInput.setAttribute('aria-label', 'Describe your ' + tool.article);
    els.toolCue.textContent = tool.cue;
    els.placeButtonLabel.textContent = tool.button;
    updateInputState();
  }

  function updateInputState() {
    var length = els.gestureInput.value.length;
    els.charCount.textContent = length + ' / 600';
    els.placeButton.disabled = els.gestureInput.value.trim().length < 8;
  }

  function handleSubmit(event) {
    event.preventDefault();
    if (!state) {
      return;
    }
    var text = E.normalizeText(els.gestureInput.value);
    if (text.length < 8) {
      showToast('A gesture needs more than a wish. Give the material a sentence.', 'error');
      els.gestureInput.focus();
      return;
    }
    var latest = state.receipts[state.receipts.length - 1];
    if (latest && latest.kind === selectedTool && latest.text === text) {
      showToast('The world has already received that exact gesture. Change one word, or choose another hand.', 'error');
      return;
    }

    var result;
    try {
      result = E.applyGesture(state, selectedTool, text, new Date().toISOString());
    } catch (error) {
      showToast(error.message || 'The gesture could not be placed.', 'error');
      return;
    }

    state = result.world;
    selectedSeq = result.receipt.seq;
    newSeq = result.receipt.seq;
    writeLocalWorld();
    renderAll(newSeq);
    newSeq = null;
    els.gestureInput.value = '';
    updateInputState();
    queueServerSave();
    playGestureSound(selectedTool);
    els.gestureInput.focus();

    if (result.receipt.pressure) {
      showToast('The world pushed back. A new pressure entered the ledger.');
    } else {
      showToast('The gesture held without opening a new pressure.');
    }
  }

  /* ------------------------------------------------------------
     The field: a deterministic celestial map
     ------------------------------------------------------------ */

  var CX = 380;
  var CY = 310;

  function svgEl(tag, attrs, text) {
    var node = document.createElementNS(SVG_NS, tag);
    if (attrs) {
      Object.keys(attrs).forEach(function (key) {
        node.setAttribute(key, attrs[key]);
      });
    }
    if (text !== undefined && text !== null) {
      node.textContent = text;
    }
    return node;
  }

  function polar(angle, radius) {
    var radians = (angle - 90) * Math.PI / 180;
    return {
      x: CX + Math.cos(radians) * radius,
      y: CY + Math.sin(radians) * radius
    };
  }

  function arcPath(radius, startAngle, endAngle) {
    var start = polar(startAngle, radius);
    var end = polar(endAngle, radius);
    var delta = Math.abs(endAngle - startAngle);
    var large = delta > 180 ? 1 : 0;
    var sweep = endAngle > startAngle ? 1 : 0;
    return 'M ' + start.x.toFixed(3) + ' ' + start.y.toFixed(3) +
      ' A ' + radius + ' ' + radius + ' 0 ' + large + ' ' + sweep + ' ' +
      end.x.toFixed(3) + ' ' + end.y.toFixed(3);
  }

  function mulberry32(seed) {
    var value = seed >>> 0;
    return function () {
      value += 0x6D2B79F5;
      var t = value;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function appendLine(parent, x1, y1, x2, y2, options) {
    var attrs = {
      x1: x1.toFixed(3),
      y1: y1.toFixed(3),
      x2: x2.toFixed(3),
      y2: y2.toFixed(3),
      stroke: options.color || '#efe6d1',
      'stroke-width': options.width || 0.7,
      'stroke-linecap': 'round'
    };
    if (options.opacity !== undefined) {
      attrs.opacity = options.opacity;
    }
    if (options.dash) {
      attrs['stroke-dasharray'] = options.dash;
    }
    if (options.className) {
      attrs['class'] = options.className;
    }
    var line = svgEl('line', attrs);
    parent.appendChild(line);
    return line;
  }

  function renderField(animateSeq) {
    if (!state) {
      return;
    }
    var scene = els.worldScene;
    while (scene.firstChild) {
      scene.removeChild(scene.firstChild);
    }

    var seed = state.id + '|' + state.question + '|' + state.inheritance.sha256;
    var random = mulberry32(E.hashInt(seed));

    scene.appendChild(renderStars(random));

    var graticule = svgEl('g', { 'class': 'graticule' });
    [72, 132, 192, 252].forEach(function (radius) {
      graticule.appendChild(svgEl('circle', {
        cx: CX, cy: CY, r: radius,
        fill: 'none', stroke: 'rgba(239,230,209,.06)', 'stroke-width': '.6',
        'stroke-dasharray': '1 8'
      }));
    });
    for (var spoke = 0; spoke < 12; spoke += 1) {
      var start = polar(spoke * 30, 64);
      var end = polar(spoke * 30, 292);
      appendLine(graticule, start.x, start.y, end.x, end.y, {
        color: 'rgba(239,230,209,.03)', width: '.55'
      });
    }
    for (var tick = 0; tick < 60; tick += 1) {
      var angle = tick * 6;
      var a = polar(angle, 286);
      var b = polar(angle, tick % 5 === 0 ? 296 : 291);
      appendLine(graticule, a.x, a.y, b.x, b.y, {
        color: 'rgba(239,230,209,.13)', width: '.55', opacity: tick % 5 === 0 ? '.8' : '.4'
      });
    }
    scene.appendChild(graticule);
    scene.appendChild(renderCoreHalo());

    var strata = svgEl('g', { 'class': 'strata' });
    state.receipts.forEach(function (receipt) {
      var group = renderStratum(receipt, receipt.seq === selectedSeq);
      if (animateSeq !== null && animateSeq !== undefined && receipt.seq === animateSeq) {
        group.classList.add('is-new');
      }
      strata.appendChild(group);
    });
    scene.appendChild(strata);
    scene.appendChild(renderCoreSigil());

    var open = E.openTensions(state).length;
    if (els.worldSvgDesc) {
      els.worldSvgDesc.textContent = 'A celestial workbench map with ' + state.receipts.length +
        ' chained receipts and ' + open + ' open pressures. The selected gesture is ' +
        (receiptBySeq(selectedSeq) ? KIND_LABELS[receiptBySeq(selectedSeq).kind].toLowerCase() : 'none') + '.';
    }
  }

  function renderStars(random) {
