  function renderProbeStratum(group, receipt, color, angle, radius) {
    var shift = (receipt.motif.variant || 0) * 7;
    group.appendChild(svgEl('path', {
      d: arcPath(radius, angle - 58 - shift, angle + 26 - shift),
      'class': 'stratum-line',
      stroke: color,
      'stroke-width': '.95',
      opacity: '.72',
      'stroke-dasharray': '1 6'
    }));
    var inner = polar(angle, 64);
    var outer = polar(angle, radius - 7);
    appendLine(group, inner.x, inner.y, outer.x, outer.y, {
      color: color, width: '.6', opacity: '.38', dash: '2 8', className: 'stratum-line'
    });
    var eye = polar(angle, radius);
    group.appendChild(svgEl('circle', {
      cx: eye.x, cy: eye.y, r: 8.5, fill: 'rgba(8,11,18,.74)', stroke: color,
      'stroke-width': '.9', opacity: '.9', 'class': 'stratum-line'
    }));
    group.appendChild(svgEl('circle', {
      cx: eye.x, cy: eye.y, r: 2.1, fill: color, opacity: '.9'
    }));
    appendLine(group, eye.x - 12, eye.y, eye.x + 12, eye.y, {
      color: color, width: '.4', opacity: '.2'
    });
    appendLine(group, eye.x, eye.y - 12, eye.x, eye.y + 12, {
      color: color, width: '.4', opacity: '.2'
    });
    addStratumLabel(group, receipt, radius + 19);
  }

  function renderChiselStratum(group, receipt, color, angle, radius) {
    var shift = (receipt.motif.variant || 0) * 4;
    group.appendChild(svgEl('path', {
      d: arcPath(radius, angle - 52 - shift, angle - 8 - shift),
      'class': 'stratum-line', stroke: color, 'stroke-width': '1.05', opacity: '.74'
    }));
    group.appendChild(svgEl('path', {
      d: arcPath(radius, angle + 8 + shift, angle + 52 + shift),
      'class': 'stratum-line', stroke: color, 'stroke-width': '1.05', opacity: '.74'
    }));
    var cutIn = polar(angle, radius - 26);
    var cutOut = polar(angle, radius + 24);
    appendLine(group, cutIn.x, cutIn.y, cutOut.x, cutOut.y, {
      color: color, width: '1.15', opacity: '.92', className: 'stratum-line'
    });
    var shadowIn = polar(angle + 17, radius - 10);
    var shadowOut = polar(angle + 17, radius + 9);
    appendLine(group, shadowIn.x, shadowIn.y, shadowOut.x, shadowOut.y, {
      color: color, width: '.45', opacity: '.2', className: 'stratum-line'
    });
    addStratumLabel(group, receipt, radius + 24);
  }

  function renderBeamStratum(group, receipt, color, angle, radius) {
    var start = polar(angle, 66);
    var end = polar(angle, radius);
    var normal = polar(angle + 90, 2.2);
    var normalOffsetX = normal.x - CX;
    var normalOffsetY = normal.y - CY;
    appendLine(group, start.x - normalOffsetX, start.y - normalOffsetY,
      end.x - normalOffsetX, end.y - normalOffsetY, {
        color: color, width: '.62', opacity: '.66', className: 'stratum-line'
      });
    appendLine(group, start.x + normalOffsetX, start.y + normalOffsetY,
      end.x + normalOffsetX, end.y + normalOffsetY, {
        color: color, width: '.62', opacity: '.66', className: 'stratum-line'
      });
    [0.34, 0.67].forEach(function (fraction) {
      var p = polar(angle, 66 + (radius - 66) * fraction);
      var n = polar(angle + 90, 6);
      appendLine(group, p.x - (n.x - CX), p.y - (n.y - CY), p.x + (n.x - CX), p.y + (n.y - CY), {
        color: color, width: '.55', opacity: '.4', className: 'stratum-line'
      });
    });
    var dx = end.x - CX;
    var dy = end.y - CY;
    var length = Math.sqrt(dx * dx + dy * dy) || 1;
    var ux = dx / length;
    var uy = dy / length;
    var px = -uy;
    var py = ux;
    var back = { x: end.x - ux * 8, y: end.y - uy * 8 };
    group.appendChild(svgEl('path', {
      d: 'M ' + end.x + ' ' + end.y + ' L ' + (back.x + px * 4.5) + ' ' + (back.y + py * 4.5) +
        ' L ' + (back.x + ux * 2) + ' ' + (back.y + uy * 2) +
        ' L ' + (back.x - px * 4.5) + ' ' + (back.y - py * 4.5) + ' Z',
      fill: color, opacity: '.78'
    }));
    addStratumLabel(group, receipt, radius + 17);
  }

  function renderBoundaryStratum(group, receipt, color, angle, radius) {
    group.appendChild(svgEl('path', {
      d: arcPath(radius, angle + 13, angle + 347),
