    }));
    var postA = polar(angle - 5, radius - 15);
    var postB = polar(angle - 5, radius + 13);
    var postC = polar(angle + 5, radius - 15);
    var postD = polar(angle + 5, radius + 13);
    appendLine(group, postA.x, postA.y, postB.x, postB.y, {
      color: color, width: '1.05', opacity: '.8', className: 'stratum-line'
    });
    appendLine(group, postC.x, postC.y, postD.x, postD.y, {
      color: color, width: '1.05', opacity: '.8', className: 'stratum-line'
    });
    var thresholdA = polar(angle - 5, radius + 13);
    var thresholdB = polar(angle + 5, radius + 13);
    appendLine(group, thresholdA.x, thresholdA.y, thresholdB.x, thresholdB.y, {
      color: color, width: '.6', opacity: '.45', className: 'stratum-line'
    });
    addStratumLabel(group, receipt, radius + 23);
  }

  function renderRehearsalStratum(group, receipt, color, angle, radius) {
    var offset = (receipt.motif.variant || 0) % 2 === 0 ? 7 : -7;
    group.appendChild(svgEl('circle', {
      cx: CX, cy: CY, r: radius, fill: 'none', stroke: color,
      'stroke-width': '.72', opacity: '.4', 'stroke-dasharray': '4 9', 'class': 'stratum-line'
    }));
    group.appendChild(svgEl('circle', {
