      'class': 'stratum-line', stroke: color, 'stroke-width': '.55', opacity: '.32',
      'stroke-dasharray': '1 7'
    }));
    var start = polar(angle + 180, 66);
    var end = polar(angle + 180, radius - 20);
    appendLine(group, start.x, start.y, end.x, end.y, {
      color: color, width: '.45', opacity: '.2', dash: '1 9', className: 'stratum-line'
    });
    var ghost = polar(angle, radius);
    group.appendChild(svgEl('circle', {
      cx: ghost.x, cy: ghost.y, r: 3.5, fill: 'none', stroke: color,
      'stroke-width': '.6', opacity: '.45', 'class': 'stratum-line'
    }));
    addStratumLabel(group, receipt, radius + 19);
  }

  function addStratumLabel(group, receipt, suggestedRadius) {
    var motif = receipt.motif || {};
    var angle = Number(motif.angle) || 0;
    var radius = Math.min(292, Math.max(74, Number(suggestedRadius) || (Number(motif.radius) || 120) + 17));
    var point = polar(angle, radius);
    var x = Math.max(18, Math.min(742, point.x));
    var y = Math.max(16, Math.min(604, point.y));
    var anchor = x < CX - 20 ? 'start' : (x > CX + 20 ? 'end' : 'middle');
    var label = String(motif.label || receipt.kind).slice(0, 26);
    var node = svgEl('text', {
      x: x.toFixed(2),
      y: y.toFixed(2),
      'text-anchor': anchor,
      'dominant-baseline': 'middle',
      'class': 'stratum-label',
      style: 'paint-order:stroke;stroke:#080b12;stroke-width:3px;stroke-linejoin:round'
    }, label);
    group.appendChild(node);
  }

  /* ------------------------------------------------------------
     Events and dialogs
     ------------------------------------------------------------ */

  function bindEvents() {
    var tools = document.querySelectorAll('.tool');
    for (var i = 0; i < tools.length; i += 1) {
      tools[i].addEventListener('click', function (event) {
        setTool(event.currentTarget.getAttribute('data-tool'));
      });
    }

    els.gestureForm.addEventListener('submit', handleSubmit);
    els.gestureInput.addEventListener('input', updateInputState);

    els.memoryButton.addEventListener('click', function () { openDialog(els.memoryDialog); });
    els.memoryLink.addEventListener('click', function () { openDialog(els.memoryDialog); });
    els.protocolButton.addEventListener('click', openProtocol);
    els.doorButton.addEventListener('click', openDoor);
    els.soundButton.addEventListener('click', toggleSound);

    var closers = document.querySelectorAll('[data-close]');
    for (var c = 0; c < closers.length; c += 1) {
      closers[c].addEventListener('click', function (event) {
        closeDialog(byId(event.currentTarget.getAttribute('data-close')));
      });
    }

    [els.memoryDialog, els.protocolDialog, els.doorDialog].forEach(function (dialog) {
      dialog.addEventListener('click', function (event) {
        if (event.target === dialog) {
          dialog.close();
        }
      });
    });

    els.exportButton.addEventListener('click', function () {
      downloadWorld();
    });
    els.downloadWorldButton.addEventListener('click', function () {
      downloadWorld();
    });
    els.downloadHandoffButton.addEventListener('click', function () {
      downloadHandoff();
    });
    els.copyHandoffButton.addEventListener('click', copyHandoff);
    els.importButton.addEventListener('click', function () {
      els.importInput.click();
    });
    els.importInput.addEventListener('change', importWorldFile);
    els.resetButton.addEventListener('click', resetWorld);

    document.addEventListener('keydown', handleKeydown);
    window.addEventListener('pagehide', flushOnPageHide);
  }

  function openDialog(dialog) {
    if (!dialog) {
      return;
    }
    var openDialogs = document.querySelectorAll('dialog[open]');
    for (var i = 0; i < openDialogs.length; i += 1) {
      if (openDialogs[i] !== dialog) {
        openDialogs[i].close();
      }
    }
    if (typeof dialog.showModal === 'function') {
      if (!dialog.open) {
        dialog.showModal();
      }
    } else {
      dialog.setAttribute('open', '');
    }
  }

  function closeDialog(dialog) {
    if (!dialog) {
      return;
    }
    if (typeof dialog.close === 'function' && dialog.open) {
      dialog.close();
    } else {
      dialog.removeAttribute('open');
    }
  }

  function openProtocol() {
    if (els.protocolSaveStatus) {
      els.protocolSaveStatus.textContent = serverReachable
        ? 'Living archive: world/state.json + this browser.'
        : 'Living archive: this browser only. Export the world for a filesystem trail.';
    }
    openDialog(els.protocolDialog);
  }

  function openDoor() {
    if (!state) {
      return;
    }
    els.doorText.textContent = E.generateHandoff(state);
    els.doorSaveNote.textContent = serverReachable
      ? 'The living copy is world/state.json when the workbench server is running. This export is a portable door.'
      : 'This copy lives in the browser. Download the world to leave a filesystem trail.';
    openDialog(els.doorDialog);
  }

  function copyHandoff() {
    var text = E.generateHandoff(state);
    copyText(text).then(function () {
      showToast('The continuation was copied. It carries the exact receipt count and fingerprint.');
    }).catch(function () {
      els.doorText.focus();
      showToast('Copy was blocked. The handoff is selected in the paper; copy it by hand.', 'error');
      selectNodeText(els.doorText);
    });
  }

  function copyText(text) {
    if (navigator.clipboard && window.isSecureContext) {
      return navigator.clipboard.writeText(text).catch(function () {
        return fallbackCopy(text);
      });
    }
    return fallbackCopy(text);
  }

  function fallbackCopy(text) {
    try {
      var area = document.createElement('textarea');
      area.value = text;
      area.setAttribute('readonly', '');
      area.style.position = 'fixed';
      area.style.left = '-9999px';
      area.style.top = '0';
      document.body.appendChild(area);
      area.select();
      var succeeded = document.execCommand('copy');
      document.body.removeChild(area);
      if (!succeeded) {
        throw new Error('Copy command failed.');
      }
      return Promise.resolve();
    } catch (error) {
      return Promise.reject(error);
    }
  }

  function selectNodeText(node) {
    if (!node) {
      return;
    }
    var range = document.createRange();
    range.selectNodeContents(node);
    var selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);
  }

  function downloadWorld() {
    if (!state) {
      return;
    }
    var filename = 'tendora-' + slugify(state.title) + '-r' + pad(state.revision) + '.json';
    downloadContent(filename, JSON.stringify(state, null, 2) + '\n', 'application/json');
    showToast('The world was exported as ' + filename + '.');
  }

  function downloadHandoff() {
    if (!state) {
      return;
    }
    var filename = 'handoff-' + slugify(state.title) + '-r' + pad(state.revision) + '.md';
    downloadContent(filename, E.generateHandoff(state), 'text/markdown');
    showToast('The handoff was exported as ' + filename + '.');
  }

  function downloadContent(filename, content, mimeType) {
    var blob = new Blob([content], { type: mimeType + ';charset=utf-8' });
    var url = URL.createObjectURL(blob);
    var anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    document.body.appendChild(anchor);
    anchor.click();
    document.body.removeChild(anchor);
    window.setTimeout(function () {
      URL.revokeObjectURL(url);
    }, 1200);
  }

  function slugify(value) {
    var slug = String(value || 'world').toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 56);
    return slug || 'world';
  }

  function importWorldFile(event) {
    var file = event.target.files && event.target.files[0];
    event.target.value = '';
    if (!file) {
      return;
    }
    var reader = new FileReader();
    reader.onload = function () {
      var parsed;
      try {
        parsed = JSON.parse(String(reader.result));
      } catch (error) {
        showToast('That file is not valid JSON.', 'error');
        return;
      }
      var validated = E.validateWorld(parsed);
      if (!validated.ok) {
        showToast('That is not a valid Tendora world: ' + validated.errors[0], 'error');
        return;
      }
      var confirmed = window.confirm('Import “' + parsed.title + '” at revision ' + parsed.revision +
        '? This replaces the world currently open in this workbench.');
      if (!confirmed) {
        return;
      }
      state = parsed;
      selectedSeq = state.receipts[state.receipts.length - 1].seq;
      writeLocalWorld();
      renderAll(null);
      closeDialog(els.protocolDialog);
      queueServerSave(40);
      if (!serverReachable) {
        setSaveStatus('local', 'browser only');
      }
      showToast('Imported “' + state.title + '”. The ledger remains chained.');
    };
    reader.onerror = function () {
      showToast('The file could not be read.', 'error');
    };
    reader.readAsText(file, 'utf-8');
  }

  async function resetWorld() {
    var confirmed = window.confirm('Restore the inherited beginning? This replaces the current world in this browser and, when the server is running, in world/state.json. Export the world first if you want to keep it.');
    if (!confirmed) {
      return;
    }
    var seed = null;
    if (serverReachable) {
      try {
        var response = await fetch('api/seed', { cache: 'no-store' });
        if (response.ok) {
          var parsed = await response.json();
          var validated = E.validateWorld(parsed);
