/* ============================================================
   TENDORA / WORKBENCH 0001
   A local-first instrument for worlds that can answer back.
   ============================================================ */

:root {
  --ink: #080b12;
  --ink-soft: #0d1220;
  --ink-raised: #111827;
  --panel: rgba(12, 17, 29, 0.72);
  --panel-solid: #0c111d;
  --paper: #efe6d1;
  --paper-soft: #e4d8bf;
  --paper-deep: #d3c4a5;
  --paper-ink: #17131a;
  --text: #e9e1d2;
  --muted: #96938c;
  --dim: #6d6c69;
  --line: rgba(239, 230, 209, 0.11);
  --line-strong: rgba(239, 230, 209, 0.21);
  --aqua: #7bd7c9;
  --copper: #db9d62;
  --violet: #a99be8;
  --rose: #d98694;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
  --sans: "Avenir Next", Avenir, "Helvetica Neue", Helvetica, Arial, sans-serif;
  --mono: "SFMono-Regular", "Menlo", "Consolas", "Liberation Mono", monospace;
  --radius: 3px;
  --shadow: 0 30px 90px rgba(0, 0, 0, 0.38);
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  min-height: 100%;
  background: var(--ink);
  color-scheme: dark;
  scroll-behavior: smooth;
}

body {
  min-height: 100vh;
  margin: 0;
  overflow-x: hidden;
  background:
    radial-gradient(ellipse 55% 42% at 18% -4%, rgba(169, 155, 232, 0.11), transparent 68%),
    radial-gradient(ellipse 52% 46% at 88% 22%, rgba(123, 215, 201, 0.055), transparent 72%),
    radial-gradient(ellipse 65% 55% at 50% 110%, rgba(219, 157, 98, 0.055), transparent 72%),
    var(--ink);
  color: var(--text);
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body::after {
  position: fixed;
  inset: 0;
  z-index: -2;
  background:
    radial-gradient(ellipse at center, transparent 45%, rgba(3, 5, 10, 0.58) 100%),
    linear-gradient(90deg, rgba(239, 230, 209, 0.015) 1px, transparent 1px),
    linear-gradient(rgba(239, 230, 209, 0.012) 1px, transparent 1px);
  background-size: 100% 100%, 96px 96px, 96px 96px;
  content: "";
  pointer-events: none;
}

::selection {
  background: rgba(219, 157, 98, 0.34);
  color: #fff8eb;
}

a {
  color: inherit;
}

button,
textarea,
input {
  font: inherit;
}

button {
  color: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

:focus-visible {
  outline: 1px solid var(--copper);
  outline-offset: 3px;
}

[hidden] {
  display: none !important;
}

.visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.skip-link {
  position: fixed;
  top: 10px;
  left: 10px;
  z-index: 100;
  padding: 10px 14px;
  transform: translateY(-160%);
  background: var(--paper);
  color: var(--paper-ink);
  font: 10px/1 var(--mono);
  letter-spacing: 0.08em;
  text-decoration: none;
  text-transform: uppercase;
  transition: transform 160ms var(--ease);
}

.skip-link:focus {
  transform: translateY(0);
}

.atmosphere {
  position: fixed;
  inset: 0;
  z-index: -1;
  overflow: hidden;
  pointer-events: none;
}

.atmosphere-glow {
  position: absolute;
  width: 48vw;
  height: 48vw;
  border-radius: 50%;
  filter: blur(90px);
  opacity: 0.16;
}

.glow-one {
  top: -26vw;
  left: -10vw;
  background: var(--violet);
}

.glow-two {
  right: -22vw;
  bottom: -20vw;
  background: var(--copper);
  opacity: 0.09;
}

.atmosphere-grain {
  position: absolute;
  inset: -30%;
  opacity: 0.14;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/></svg>");
  mix-blend-mode: soft-light;
  transform: rotate(9deg);
}

/* ------------------------------------------------------------
   Masthead
   ------------------------------------------------------------ */

.masthead {
  position: sticky;
  top: 0;
  z-index: 20;
  display: grid;
  grid-template-columns: minmax(220px, 1fr) auto minmax(220px, 1fr);
  align-items: center;
  min-height: 74px;
  padding: 14px 28px;
  border-bottom: 1px solid var(--line);
  background: rgba(8, 11, 18, 0.78);
  backdrop-filter: blur(18px) saturate(120%);
  -webkit-backdrop-filter: blur(18px) saturate(120%);
}

.brand {
  display: inline-flex;
  gap: 13px;
  align-items: center;
  justify-self: start;
  color: var(--text);
  text-decoration: none;
}

.brand-mark {
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  color: var(--copper);
  transition: transform 700ms var(--ease);
}

.brand:hover .brand-mark {
  transform: rotate(45deg);
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.brand-copy strong {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.29em;
  line-height: 1;
}

.brand-copy small {
  color: var(--muted);
  font-family: var(--serif);
  font-size: 10px;
  font-style: italic;
  letter-spacing: 0.055em;
}

.bench-id {
  display: flex;
  gap: 9px;
  align-items: center;
  justify-self: center;
  color: var(--muted);
  font: 9px/1 var(--mono);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.bench-light {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--aqua);
  box-shadow: 0 0 0 3px rgba(123, 215, 201, 0.08), 0 0 12px rgba(123, 215, 201, 0.5);
}

.masthead-tools {
  display: flex;
  gap: 16px;
  align-items: center;
  justify-self: end;
}

.save-badge {
  display: flex;
  gap: 7px;
  align-items: center;
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  font: 8px/1 var(--mono);
  letter-spacing: 0.09em;
  text-transform: uppercase;
  white-space: nowrap;
}

.save-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--dim);
}

.save-badge[data-state="ready"] .save-dot {
  background: var(--aqua);
  box-shadow: 0 0 8px rgba(123, 215, 201, 0.6);
}

.save-badge[data-state="saving"] .save-dot {
  background: var(--copper);
  animation: save-pulse 1.2s ease-in-out infinite;
}

.save-badge[data-state="local"] .save-dot {
  background: var(--violet);
}

.save-badge[data-state="error"] .save-dot {
  background: var(--rose);
}

.utility-nav {
  display: flex;
  gap: 3px;
  align-items: center;
}

.nav-button {
  padding: 8px 10px;
  border: 0;
  border-radius: 2px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font: 9px/1 var(--mono);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  transition: color 160ms ease, background 160ms ease;
}

.nav-button:hover {
  background: rgba(239, 230, 209, 0.055);
  color: var(--text);
}

.sound-button {
  display: inline-flex;
  gap: 6px;
  align-items: center;
}

.sound-glyph {
  display: inline-block;
  font-size: 12px;
  line-height: 0;
  transition: transform 300ms var(--ease);
}

.sound-button[aria-pressed="true"] {
  color: var(--aqua);
}

.sound-button[aria-pressed="true"] .sound-glyph {
  transform: rotate(140deg);
}

/* ------------------------------------------------------------
   Workbench grid
   ------------------------------------------------------------ */

.workbench {
  display: grid;
  grid-template-columns: 286px minmax(0, 1fr) 324px;
  grid-template-areas: "world field ledger";
  gap: 16px;
  align-items: start;
  width: 100%;
  max-width: 1640px;
  margin: 0 auto;
  padding: 20px 24px 26px;
}

.panel {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(160deg, rgba(239, 230, 209, 0.028), transparent 24%),
    var(--panel);
  box-shadow: 0 20px 55px rgba(0, 0, 0, 0.16);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.panel-kicker {
  display: flex;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
  color: var(--muted);
  font: 8.5px/1.2 var(--mono);
  letter-spacing: 0.17em;
  text-transform: uppercase;
}

.index-mark {
  color: var(--dim);
}

.hairline {
  height: 1px;
  margin: 22px 0 20px;
  background: linear-gradient(90deg, var(--line-strong), transparent);
}

/* ------------------------------------------------------------
   World panel
   ------------------------------------------------------------ */

.world-panel {
  grid-area: world;
  padding: 20px 19px 18px;
}

.world-panel h1 {
  margin: 20px 0 15px;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(32px, 2.5vw, 42px);
  font-weight: 400;
  letter-spacing: -0.035em;
  line-height: 0.98;
  text-wrap: balance;
}

.world-question {
  margin: 0;
  color: #c8c0b2;
  font-family: var(--serif);
  font-size: 15px;
  font-style: italic;
  line-height: 1.52;
  text-wrap: pretty;
}

.world-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 7px 16px;
  margin-top: 18px;
  color: var(--dim);
  font: 8px/1.4 var(--mono);
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.world-meta b {
  color: var(--muted);
  font-weight: 500;
}

.pulse-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 13px;
  color: var(--muted);
  font: 8px/1 var(--mono);
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.pulse-word {
  color: var(--copper);
  font-family: var(--serif);
  font-size: 11px;
  font-style: italic;
  letter-spacing: 0.02em;
  text-transform: lowercase;
}

.facets {
  display: grid;
  gap: 10px;
}

.facet {
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr) 22px;
  gap: 9px;
  align-items: center;
}

.facet-name {
  color: var(--muted);
  font: 7.5px/1 var(--mono);
  letter-spacing: 0.13em;
}

.facet-track {
  position: relative;
  display: block;
  height: 2px;
  overflow: hidden;
  background: rgba(239, 230, 209, 0.08);
}

.facet-track i {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 0;
  background: var(--facet-color, var(--copper));
  box-shadow: 0 0 10px color-mix(in srgb, var(--facet-color, var(--copper)) 42%, transparent);
  transition: width 900ms var(--ease);
}

.facet[data-facet="form"] { --facet-color: var(--copper); }
.facet[data-facet="weather"] { --facet-color: var(--aqua); }
.facet[data-facet="care"] { --facet-color: var(--violet); }
.facet[data-facet="resistance"] { --facet-color: var(--rose); }

.facet-value {
  color: var(--dim);
  font: 8px/1 var(--mono);
  text-align: right;
}

.inheritance-note {
  margin: 24px 0 16px;
  padding: 0 0 0 12px;
  border-left: 1px solid rgba(219, 157, 98, 0.55);
  color: var(--muted);
  font-family: var(--serif);
  font-size: 12px;
  font-style: italic;
  line-height: 1.55;
}

.text-link {
  display: inline-flex;
  gap: 7px;
  align-items: center;
  padding: 0;
  border: 0;
  border-bottom: 1px solid rgba(219, 157, 98, 0.34);
  background: transparent;
  color: var(--copper);
  cursor: pointer;
  font: 8.5px/1.8 var(--mono);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  transition: color 160ms ease, border-color 160ms ease;
}

.text-link:hover {
  border-color: var(--copper);
  color: #f1bd86;
}

.text-link span {
  transition: transform 180ms var(--ease);
}

.text-link:hover span {
  transform: translate(2px, -2px);
}

.panel-footnote {
  margin: 26px 0 0;
  padding-top: 14px;
  border-top: 1px solid var(--line);
  color: var(--dim);
  font: 8px/1.65 var(--mono);
  letter-spacing: 0.04em;
}

/* ------------------------------------------------------------
