   ------------------------------------------------------------ */

.field-panel {
  grid-area: field;
  min-width: 0;
}

.field-top {
  display: flex;
  gap: 20px;
  align-items: baseline;
  justify-content: space-between;
  padding: 0 3px 11px;
}

.field-heading {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  align-items: baseline;
}

.field-count {
  color: var(--dim);
  font: 8px/1 var(--mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.gesture-jump {
  display: none;
  gap: 7px;
  align-items: center;
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 2px;
  color: var(--copper);
  font: 7.5px/1 var(--mono);
  letter-spacing: 0.08em;
  text-decoration: none;
  text-transform: uppercase;
}

.gesture-jump:hover {
  border-color: rgba(219, 157, 98, 0.55);
  background: rgba(219, 157, 98, 0.06);
}

.weather {
  color: var(--aqua);
  font-family: var(--serif);
  font-size: 12px;
  font-style: italic;
  letter-spacing: 0.01em;
  text-align: right;
}

.field-stage {
  position: relative;
  height: clamp(330px, 44vh, 540px);
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    radial-gradient(circle at 50% 46%, rgba(123, 215, 201, 0.045), transparent 34%),
    radial-gradient(circle at 50% 55%, rgba(169, 155, 232, 0.035), transparent 56%),
    linear-gradient(180deg, rgba(13, 18, 32, 0.86), rgba(6, 9, 16, 0.92));
  box-shadow: inset 0 0 120px rgba(0, 0, 0, 0.38), var(--shadow);
}

.field-stage::before {
  position: absolute;
  inset: 0;
  z-index: 0;
  background:
    linear-gradient(90deg, rgba(239, 230, 209, 0.025) 1px, transparent 1px),
    linear-gradient(rgba(239, 230, 209, 0.018) 1px, transparent 1px);
  background-size: 76px 76px;
  mask-image: radial-gradient(circle at center, #000 15%, transparent 76%);
  content: "";
  pointer-events: none;
}

.field-stage::after {
  position: absolute;
  inset: 0;
  z-index: 2;
  background: radial-gradient(ellipse at center, transparent 52%, rgba(4, 6, 12, 0.38) 100%);
  content: "";
  pointer-events: none;
}

.world-svg {
  position: relative;
  z-index: 1;
  display: block;
  width: 100%;
  height: 100%;
}

.star {
  fill: #f4e9d4;
  opacity: 0.52;
  animation: twinkle 5.5s ease-in-out infinite;
}

.star-major {
  fill: var(--copper);
  opacity: 0.72;
}


.graticule {
  fill: none;
  stroke: rgba(239, 230, 209, 0.065);
  stroke-width: 0.65;
  stroke-dasharray: 1 8;
}

.spoke {
  stroke: rgba(239, 230, 209, 0.035);
  stroke-width: 0.6;
}

.stratum {
  cursor: pointer;
  transition: opacity 240ms ease;
}

.stratum:hover {
  opacity: 1;
}

.stratum .stratum-line {
  fill: none;
  stroke-linecap: round;
  transition: stroke-width 220ms ease, opacity 220ms ease;
}

.stratum .stratum-fill {
  transition: opacity 240ms ease;
}

.stratum-label {
  fill: var(--muted);
  font: 10.5px var(--mono);
  letter-spacing: 1.1px;
  opacity: 0.72;
  pointer-events: none;
  text-transform: uppercase;
  transition: fill 180ms ease, opacity 180ms ease;
}

.stratum.is-selected .stratum-label {
  fill: var(--text);
  opacity: 1;
}

.stratum.is-selected .stratum-line {
  filter: url(#softGlow);
  stroke-width: 1.65;
}

.stratum.is-new {
  animation: stratum-arrive 1.1s var(--ease) both;
  transform-origin: 380px 310px;
}

.core-halo {
  animation: breathe 7s ease-in-out infinite;
  transform-origin: 380px 310px;
}

.core-sigil {
  animation: spin-slow 80s linear infinite;
  transform-origin: 380px 310px;
}

.core-sigil-reverse {
  animation: spin-slow 120s linear infinite reverse;
  transform-origin: 380px 310px;
}

.field-corner {
  position: absolute;
  z-index: 3;
  width: 16px;
  height: 16px;
  opacity: 0.45;
  pointer-events: none;
}

.corner-tl { top: 10px; left: 10px; border-top: 1px solid var(--copper); border-left: 1px solid var(--copper); }
.corner-tr { top: 10px; right: 10px; border-top: 1px solid var(--copper); border-right: 1px solid var(--copper); }
.corner-bl { bottom: 10px; left: 10px; border-bottom: 1px solid var(--copper); border-left: 1px solid var(--copper); }
.corner-br { bottom: 10px; right: 10px; border-bottom: 1px solid var(--copper); border-right: 1px solid var(--copper); }

.field-scale {
  position: absolute;
  right: 15px;
  bottom: 12px;
  left: 15px;
  z-index: 3;
  display: flex;
  justify-content: space-between;
  color: var(--dim);
  font: 6.5px/1 var(--mono);
  letter-spacing: 0.13em;
  opacity: 0.7;
  pointer-events: none;
}

/* ------------------------------------------------------------
   Answer
   ------------------------------------------------------------ */

.answer-card {
  position: relative;
  margin-top: 12px;
  padding: 15px 18px 14px 19px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-left: 2px solid var(--answer-accent, var(--copper));
  border-radius: 2px;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--answer-accent, var(--copper)) 5%, transparent), transparent 28%),
    rgba(10, 14, 24, 0.82);
}

.answer-card::after {
  position: absolute;
  top: 0;
  right: 0;
  width: 42%;
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--answer-accent, var(--copper)) 45%, transparent));
  content: "";
}

.answer-card.is-changing {
  animation: answer-arrive 460ms var(--ease) both;
}

.answer-head {
  display: flex;
  gap: 20px;
  align-items: baseline;
  justify-content: space-between;
}

.answer-meta {
  color: var(--answer-accent, var(--copper));
  font: 8px/1.2 var(--mono);
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.answer-stamp {
  color: var(--dim);
  font: 7.5px/1.2 var(--mono);
  letter-spacing: 0.05em;
  white-space: nowrap;
}

.answer-copy {
  max-width: 70ch;
  margin: 10px 0 0;
  color: #d8d0c2;
  font-family: var(--serif);
  font-size: clamp(15px, 1.24vw, 18px);
  line-height: 1.54;
  text-wrap: pretty;
}

.answer-pressure {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  gap: 12px;
  align-items: baseline;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
}

.pressure-label {
  color: var(--rose);
  font: 7px/1 var(--mono);
  letter-spacing: 0.13em;
  white-space: nowrap;
}

.answer-pressure p {
  margin: 0;
  color: #b9afa4;
  font-family: var(--serif);
  font-size: 12px;
  font-style: italic;
  line-height: 1.45;
}

/* ------------------------------------------------------------
   Composer
   ------------------------------------------------------------ */

.composer {
  scroll-margin-top: 88px;
  margin-top: 12px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(11, 15, 26, 0.68);
}

.tool-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 10px;
}

.shortcut-hint {
  color: var(--dim);
  font: 7px/1 var(--mono);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.tool-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
  margin-bottom: 9px;
}

.tool {
  display: flex;
  gap: 9px;
  align-items: center;
  min-width: 0;
  padding: 9px 9px 8px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: rgba(239, 230, 209, 0.016);
  color: var(--muted);
  cursor: pointer;
  text-align: left;
  transition: border-color 180ms ease, background 180ms ease, color 180ms ease, transform 180ms var(--ease);
}

.tool[data-tool="probe"] { --tool-accent: var(--aqua); }
.tool[data-tool="chisel"] { --tool-accent: var(--copper); }
.tool[data-tool="beam"] { --tool-accent: var(--paper); }
.tool[data-tool="boundary"] { --tool-accent: var(--violet); }
.tool[data-tool="rehearsal"] { --tool-accent: var(--rose); }

.tool:hover {
  border-color: var(--line-strong);
  background: rgba(239, 230, 209, 0.035);
  color: var(--text);
  transform: translateY(-1px);
}

.tool.is-active {
  border-color: color-mix(in srgb, var(--tool-accent) 48%, transparent);
  background:
    linear-gradient(150deg, color-mix(in srgb, var(--tool-accent) 12%, transparent), transparent 74%),
    rgba(239, 230, 209, 0.018);
  color: var(--text);
  box-shadow: inset 0 -1px 0 color-mix(in srgb, var(--tool-accent) 42%, transparent);
}

.tool-icon {
  display: grid;
  flex: 0 0 auto;
  width: 25px;
  height: 25px;
  place-items: center;
  color: var(--tool-accent);
}

.tool-icon svg {
  width: 21px;
  height: 21px;
  overflow: visible;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.15;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.tool-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.tool-copy strong {
  overflow: hidden;
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.04em;
  line-height: 1.2;
  text-overflow: ellipsis;
}

.tool-copy small {
  color: var(--dim);
  font: 7px/1 var(--mono);
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.tool.is-active .tool-copy small {
  color: color-mix(in srgb, var(--tool-accent) 72%, var(--muted));
}

.input-shell {
  position: relative;
}

#gestureInput {
  display: block;
  width: 100%;
  min-height: 72px;
  max-height: 180px;
  resize: vertical;
  padding: 13px 62px 13px 14px;
  border: 1px solid var(--line);
  border-radius: 2px;
  outline: none;
  background: rgba(0, 0, 0, 0.22);
  color: var(--text);
  font-family: var(--serif);
  font-size: 15px;
  line-height: 1.5;
  transition: border-color 180ms ease, background 180ms ease;
}

#gestureInput::placeholder {
  color: #716e68;
  font-style: italic;
}

#gestureInput:hover {
  border-color: var(--line-strong);
}

#gestureInput:focus {
  border-color: rgba(219, 157, 98, 0.55);
  background: rgba(0, 0, 0, 0.28);
}

.char-count {
  position: absolute;
  right: 11px;
  bottom: 9px;
  color: var(--dim);
  font: 7px/1 var(--mono);
  letter-spacing: 0.04em;
}

.form-row {
  display: flex;
  gap: 18px;
  align-items: center;
  justify-content: space-between;
  margin-top: 9px;
}

.tool-cue {
  max-width: 58%;
  margin: 0;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 11px;
  font-style: italic;
  line-height: 1.4;
}

.place-button {
  display: inline-flex;
  gap: 14px;
  align-items: center;
  justify-content: space-between;
  min-width: 150px;
  min-height: 42px;
  padding: 0 15px;
  border: 1px solid var(--paper);
  border-radius: 2px;
  background: var(--paper);
  color: var(--paper-ink);
  cursor: pointer;
  font: 8px/1 var(--mono);
  letter-spacing: 0.11em;
  text-transform: uppercase;
  transition: background 180ms ease, color 180ms ease, border-color 180ms ease, transform 180ms var(--ease), opacity 180ms ease;
}

.place-button:not(:disabled):hover {
  border-color: var(--copper);
  background: var(--copper);
  transform: translateY(-1px);
}

.place-button:not(:disabled):active {
  transform: translateY(0);
}

.place-button:disabled {
  cursor: not-allowed;
  opacity: 0.28;
}

.place-arrow {
  font-size: 13px;
  transition: transform 180ms var(--ease);
}

.place-button:not(:disabled):hover .place-arrow {
  transform: translateX(3px);
}

.composer-footnote {
  margin: 8px 0 0;
  color: var(--dim);
  font: 7px/1.4 var(--mono);
  letter-spacing: 0.05em;
  text-align: right;
}

/* ------------------------------------------------------------
   Ledger panel
   ------------------------------------------------------------ */

.ledger-panel {
  grid-area: ledger;
  display: flex;
  flex-direction: column;
  gap: 19px;
  padding: 18px 17px 15px;
}

.ledger-block,
.pressure-block {
  min-width: 0;
}

.receipt-list {
  display: flex;
  max-height: 294px;
  flex-direction: column;
  gap: 0;
  padding: 7px 0 0;
  margin: 0;
  overflow-y: auto;
  list-style: none;
  scrollbar-color: rgba(239, 230, 209, 0.18) transparent;
  scrollbar-width: thin;
}

.receipt-list::-webkit-scrollbar,
.tension-list::-webkit-scrollbar,
.door-paper::-webkit-scrollbar {
  width: 4px;
}

.receipt-list::-webkit-scrollbar-thumb,
.tension-list::-webkit-scrollbar-thumb,
.door-paper::-webkit-scrollbar-thumb {
  background: rgba(239, 230, 209, 0.16);
}

.receipt {
  --receipt-accent: var(--muted);
  display: grid;
  grid-template-columns: 21px minmax(0, 1fr) auto;
  gap: 7px;
  align-items: start;
  width: 100%;
  padding: 9px 5px 9px 3px;
  border: 0;
  border-bottom: 1px solid rgba(239, 230, 209, 0.06);
  border-radius: 1px;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  text-align: left;
  transition: background 160ms ease, color 160ms ease;
}

.receipt[data-kind="probe"] { --receipt-accent: var(--aqua); }
.receipt[data-kind="chisel"] { --receipt-accent: var(--copper); }
.receipt[data-kind="beam"] { --receipt-accent: var(--paper); }
.receipt[data-kind="boundary"] { --receipt-accent: var(--violet); }
.receipt[data-kind="rehearsal"] { --receipt-accent: var(--rose); }
.receipt[data-kind="memory"] { --receipt-accent: #8b877d; }
.receipt[data-kind="kindle"] { --receipt-accent: var(--copper); }

.receipt:hover {
  background: rgba(239, 230, 209, 0.035);
}

.receipt.is-active {
  background: color-mix(in srgb, var(--receipt-accent) 7%, transparent);
}

.receipt-index {
  padding-top: 2px;
  color: var(--dim);
  font: 7px/1 var(--mono);
  letter-spacing: 0.03em;
}

.receipt-body {
  min-width: 0;
}

.receipt-kind {
  display: block;
  margin-bottom: 3px;
  color: var(--receipt-accent);
  font: 7px/1 var(--mono);
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.receipt-text {
  display: -webkit-box;
  overflow: hidden;
  color: #c7c0b3;
  font-family: var(--serif);
  font-size: 11.5px;
  line-height: 1.36;
  text-wrap: pretty;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.receipt.is-active .receipt-text {
  color: var(--text);
}

.receipt-fp {
  padding-top: 2px;
  color: #5f5e5b;
  font: 6.5px/1 var(--mono);
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.pressure-block {
  padding-top: 14px;
  border-top: 1px solid var(--line);
}

.tension-list {
  display: flex;
  max-height: 188px;
  flex-direction: column;
  gap: 0;
  padding: 5px 0 0;
  margin: 0;
  overflow-y: auto;
  list-style: none;
  scrollbar-width: thin;
}

.tension-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 34px;
  gap: 8px;
  align-items: center;
  padding: 8px 0 8px 10px;
  border-bottom: 1px solid rgba(239, 230, 209, 0.055);
  border-left: 1px solid rgba(217, 134, 148, 0.36);
}

.tension-text {
  padding: 0;
  border: 0;
  background: transparent;
  color: #b8afa4;
  cursor: pointer;
  font-family: var(--serif);
  font-size: 11.5px;
  font-style: italic;
  line-height: 1.4;
  text-align: left;
  transition: color 160ms ease;
}

.tension-text:hover {
  color: var(--text);
}

.tension-take {
  padding: 4px 0;
  border: 0;
  background: transparent;
  color: var(--dim);
  cursor: pointer;
  font: 6.5px/1 var(--mono);
  letter-spacing: 0.05em;
  text-transform: uppercase;
  transition: color 160ms ease;
}

.tension-take:hover {
  color: var(--rose);
}

.pressure-note {
  margin: 10px 0 0;
  color: var(--dim);
  font: 7px/1.5 var(--mono);
  letter-spacing: 0.02em;
}

.door-button {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) auto;
  gap: 11px;
  align-items: center;
  width: 100%;
  padding: 13px 13px 12px;
  border: 1px solid var(--paper);
  border-radius: 2px;
  background:
    linear-gradient(135deg, rgba(219, 157, 98, 0.18), transparent 62%),
    var(--paper);
  color: var(--paper-ink);
  cursor: pointer;
  text-align: left;
  transition: transform 180ms var(--ease), background 180ms ease, box-shadow 180ms ease;
}

.door-button:hover {
  background:
    linear-gradient(135deg, rgba(219, 157, 98, 0.35), transparent 62%),
    #f4ead6;
  box-shadow: 0 9px 26px rgba(0, 0, 0, 0.24);
  transform: translateY(-2px);
}

.door-glyph {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border: 1px solid rgba(23, 19, 26, 0.2);
  border-radius: 50%;
}

.door-glyph svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.2;
}

.door-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.door-copy strong {
  font-family: var(--serif);
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.01em;
  line-height: 1.1;
}

.door-copy small {
  color: rgba(23, 19, 26, 0.64);
  font: 7px/1.3 var(--mono);
  letter-spacing: 0.02em;
}

.door-arrow {
  font-size: 16px;
  transition: transform 180ms var(--ease);
}

.door-button:hover .door-arrow {
  transform: translateX(3px);
}

.ledger-save {
  margin: -7px 0 0;
  color: var(--dim);
  font: 7px/1.3 var(--mono);
  letter-spacing: 0.05em;
  text-align: right;
  text-transform: uppercase;
}

/* ------------------------------------------------------------
   Colophon
   ------------------------------------------------------------ */

.colophon {
  display: flex;
  gap: 20px;
  align-items: baseline;
  justify-content: space-between;
  max-width: 1640px;
  margin: 0 auto;
  padding: 13px 24px 25px;
  border-top: 1px solid var(--line);
  color: var(--dim);
  font: 7.5px/1.5 var(--mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.colophon p {
  margin: 0;
}

.colophon p:first-child {
  color: var(--muted);
  font-family: var(--serif);
  font-size: 11px;
  font-style: italic;
  letter-spacing: 0.01em;
  text-transform: none;
}

.colophon-mark {
  margin-right: 7px;
  color: var(--copper);
  font-style: normal;
}

/* ------------------------------------------------------------
   Dialogs
   ------------------------------------------------------------ */

.dialog {
  width: auto;
  max-width: none;
  max-height: none;
  padding: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--text);
}

.dialog::backdrop {
  background: rgba(3, 5, 9, 0.76);
  backdrop-filter: blur(10px) saturate(80%);
  -webkit-backdrop-filter: blur(10px) saturate(80%);
}

.dialog[open] {
  animation: dialog-in 280ms var(--ease) both;
}

.dialog-close {
  display: grid;
  flex: 0 0 auto;
  width: 34px;
  height: 34px;
  place-items: center;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-family: var(--sans);
  font-size: 20px;
  font-weight: 300;
  line-height: 1;
  transition: color 160ms ease, border-color 160ms ease, transform 200ms var(--ease);
}

.dialog-close:hover {
  border-color: var(--line-strong);
  color: var(--text);
  transform: rotate(8deg);
}

.kicker {
  margin: 0 0 10px;
  color: var(--muted);
  font: 8px/1.3 var(--mono);
  letter-spacing: 0.17em;
  text-transform: uppercase;
}

/* Memory as paper */

.memory-dialog {
  width: min(880px, calc(100vw - 32px));
  max-height: calc(100vh - 36px);
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: rgba(23, 19, 26, 0.2) transparent;
}

.paper {
  position: relative;
  padding: clamp(26px, 4.2vw, 48px);
  border: 1px solid rgba(23, 19, 26, 0.25);
  background:
    linear-gradient(90deg, rgba(96, 76, 45, 0.035) 1px, transparent 1px),
    linear-gradient(rgba(96, 76, 45, 0.025) 1px, transparent 1px),
    radial-gradient(ellipse at 20% 0%, rgba(255, 249, 231, 0.75), transparent 45%),
    radial-gradient(ellipse at 90% 100%, rgba(140, 102, 54, 0.11), transparent 50%),
    var(--paper);
  background-size: 36px 36px, 36px 36px, 100% 100%, 100% 100%, 100% 100%;
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.55);
  color: var(--paper-ink);
}

.paper::after {
  position: absolute;
  inset: 12px;
  border: 1px solid rgba(23, 19, 26, 0.08);
  content: "";
  pointer-events: none;
}

.paper-head {
  position: relative;
  z-index: 1;
  display: flex;
  gap: 28px;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 21px;
  border-bottom: 1px solid rgba(23, 19, 26, 0.22);
}

.paper-head .kicker {
  color: rgba(23, 19, 26, 0.54);
}

.paper-head h2 {
  max-width: 650px;
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(33px, 5vw, 53px);
  font-weight: 400;
  letter-spacing: -0.035em;
  line-height: 0.98;
  text-wrap: balance;
}

.paper-close-x {
  width: 36px;
  height: 36px;
  border-color: rgba(23, 19, 26, 0.2);
  color: rgba(23, 19, 26, 0.62);
}

.paper-close-x:hover {
  border-color: rgba(23, 19, 26, 0.5);
  color: var(--paper-ink);
}

.memory-preamble {
  position: relative;
  z-index: 1;
  max-width: 670px;
  margin: 24px 0 28px;
  padding-left: 15px;
  border-left: 2px solid rgba(141, 94, 42, 0.62);
  color: rgba(23, 19, 26, 0.7);
  font-family: var(--serif);
  font-size: 14px;
  font-style: italic;
  line-height: 1.6;
}

.memory-text {
  position: relative;
  z-index: 1;
  max-width: 690px;
  margin: 0 auto;
  font-family: var(--serif);
  font-size: clamp(16px, 1.65vw, 18px);
  line-height: 1.74;
}

.memory-text p {
  margin: 0 0 1.05em;
}

.memory-text p.first {
  margin-bottom: 1.1em;
  font-size: 1.12em;
}

.memory-text p.first::first-letter {
  float: left;
  margin: 0.07em 0.1em 0 0;
  color: #7b4f2b;
  font-size: 4.1em;
  line-height: 0.72;
}

.paper-foot {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  align-items: center;
  justify-content: space-between;
  margin-top: 34px;
  padding-top: 18px;
  border-top: 1px solid rgba(23, 19, 26, 0.2);
}

.paper-checksum {
  display: flex;
  flex-direction: column;
  gap: 4px;
  color: rgba(23, 19, 26, 0.45);
  font: 7px/1.3 var(--mono);
  letter-spacing: 0.1em;
}

.paper-checksum code {
  color: rgba(23, 19, 26, 0.78);
  font-size: 9px;
  letter-spacing: 0.04em;
}

.paper-close {
  padding: 10px 0;
  border: 0;
  border-bottom: 1px solid rgba(23, 19, 26, 0.4);
  background: transparent;
  color: var(--paper-ink);
  cursor: pointer;
  font: 8px/1 var(--mono);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: border-color 160ms ease, color 160ms ease;
}

.paper-close:hover {
  border-color: var(--paper-ink);
  color: #7b4f2b;
}

/* Dark modals */

.protocol-dialog,
.door-dialog {
  width: min(790px, calc(100vw - 32px));
  max-height: calc(100vh - 36px);
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(239, 230, 209, 0.18) transparent;
}

.door-dialog {
  width: min(860px, calc(100vw - 32px));
}

.modal-shell {
  padding: clamp(22px, 3.2vw, 34px);
  border: 1px solid var(--line-strong);
  background:
    radial-gradient(circle at 88% -8%, rgba(169, 155, 232, 0.1), transparent 35%),
    linear-gradient(155deg, rgba(239, 230, 209, 0.03), transparent 24%),
    #0b101b;
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.58);
}

.modal-head {
  display: flex;
  gap: 24px;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 19px;
  border-bottom: 1px solid var(--line);
}

.modal-head h2 {
  margin: 0;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(32px, 4.1vw, 46px);
  font-weight: 400;
  letter-spacing: -0.035em;
  line-height: 0.98;
  text-wrap: balance;
}

.modal-lede {
  max-width: 68ch;
  margin: 20px 0 24px;
  color: #c8c0b3;
  font-family: var(--serif);
  font-size: clamp(15px, 1.4vw, 17px);
  line-height: 1.55;
  text-wrap: pretty;
}

.protocol-steps {
  padding: 0;
  margin: 0;
  list-style: none;
}

.protocol-steps li {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 12px;
  padding: 14px 0;
  border-top: 1px solid var(--line);
}

.protocol-steps li:last-child {
  border-bottom: 1px solid var(--line);
}

.step-number {
