  margin-bottom: 3px;
  color: var(--text);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.protocol-steps p {
  max-width: 64ch;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.55;
}

.protocol-columns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  margin: 22px 0;
  border: 1px solid var(--line);
}

.protocol-columns section {
  padding: 16px 17px;
}

.protocol-columns section + section {
  border-left: 1px solid var(--line);
}

.protocol-columns h3 {
  margin: 0 0 6px;
  color: var(--text);
  font: 8px/1 var(--mono);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.protocol-columns p {
  margin: 0;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.55;
}

code {
  padding: 0.08em 0.28em;
  border-radius: 2px;
  background: rgba(239, 230, 209, 0.07);
  color: #d9c9ad;
  font-family: var(--mono);
  font-size: 0.9em;
}

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 22px;
}

.action-button,
.action-link {
  display: inline-flex;
  gap: 12px;
  align-items: center;
  justify-content: center;
  min-height: 41px;
  padding: 0 14px;
  border: 1px solid var(--line-strong);
  border-radius: 2px;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  font: 8px/1 var(--mono);
  letter-spacing: 0.08em;
  text-decoration: none;
  text-transform: uppercase;
  transition: border-color 160ms ease, background 160ms ease, color 160ms ease;
}

.action-button:hover,
.action-link:hover {
  border-color: rgba(219, 157, 98, 0.62);
  background: rgba(219, 157, 98, 0.08);
  color: #f0c495;
}

.protocol-foot {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 18px;
  align-items: baseline;
  justify-content: space-between;
  margin-top: 19px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
  color: var(--dim);
  font: 7px/1.5 var(--mono);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.danger-link {
  padding: 0;
  border: 0;
  border-bottom: 1px solid rgba(217, 134, 148, 0.35);
  background: transparent;
  color: var(--rose);
  cursor: pointer;
  font: 7px/1.5 var(--mono);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.danger-link:hover {
  border-color: var(--rose);
}

/* Continuation receipt */

.door-shell .modal-lede {
  margin-bottom: 17px;
}

.door-paper {
  max-height: min(46vh, 430px);
  padding: 22px 24px;
  margin: 0;
  overflow: auto;
  border: 1px solid rgba(23, 19, 26, 0.24);
  background:
    linear-gradient(rgba(96, 76, 45, 0.025) 1px, transparent 1px),
    var(--paper);
  background-size: 100% 27px, 100% 100%;
  color: var(--paper-ink);
  font: 10.5px/1.62 var(--mono);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  scrollbar-color: rgba(23, 19, 26, 0.2) transparent;
}

.modal-note {
  margin: 13px 0 0;
  color: var(--dim);
  font: 7.5px/1.5 var(--mono);
  letter-spacing: 0.03em;
}

/* Toast and noscript */

.toast {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 80;
  max-width: min(360px, calc(100vw - 32px));
  padding: 11px 14px;
  transform: translateY(14px);
  border: 1px solid var(--line-strong);
  border-left: 2px solid var(--copper);
  border-radius: 2px;
  background: rgba(10, 14, 24, 0.96);
  box-shadow: 0 16px 50px rgba(0, 0, 0, 0.44);
  color: var(--text);
  font: 9px/1.5 var(--mono);
  letter-spacing: 0.02em;
  opacity: 0;
  pointer-events: none;
  transition: opacity 180ms ease, transform 260ms var(--ease);
}

.toast.is-visible {
  transform: translateY(0);
  opacity: 1;
}

.toast[data-tone="error"] {
  border-left-color: var(--rose);
}

.noscript {
  position: fixed;
  right: 20px;
  bottom: 20px;
  left: 20px;
  z-index: 90;
  padding: 14px;
  border: 1px solid var(--rose);
  background: var(--ink-soft);
  color: var(--text);
  font: 11px/1.5 var(--mono);
  text-align: center;
}

/* ------------------------------------------------------------
   Motion
   ------------------------------------------------------------ */

@keyframes twinkle {
  0%, 100% { opacity: 0.24; }
  50% { opacity: 0.78; }
}

@keyframes breathe {
  0%, 100% { opacity: 0.72; transform: scale(0.97); }
  50% { opacity: 1; transform: scale(1.035); }
}

@keyframes spin-slow {
  to { transform: rotate(360deg); }
}

@keyframes stratum-arrive {
  0% { opacity: 0; transform: scale(0.92) rotate(-2deg); }
  100% { opacity: 1; transform: scale(1) rotate(0); }
}

@keyframes answer-arrive {
  0% { opacity: 0.2; transform: translateY(6px); }
  100% { opacity: 1; transform: translateY(0); }
}

@keyframes dialog-in {
  0% { opacity: 0; transform: translateY(12px) scale(0.99); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes save-pulse {
  0%, 100% { opacity: 0.35; }
  50% { opacity: 1; }
}

