/*
 * A dependency-free DOM smoke test for the workbench UI.
 * It supplies just enough browser surface to render the inherited world,
 * open the continuation dialogs, take up a pressure, place a gesture,
 * persist the new state, and replay an older receipt.
 *
 * This is not a layout test and not a substitute for opening the page.
 * Run with: node test/dom-smoke.test.js
 */
'use strict';
const fs = require('fs');
const path = require('path');
const assert = require('assert');
const root = path.resolve(__dirname, '..');
const initialState = JSON.parse(fs.readFileSync(path.join(root, 'world/state.json'), 'utf8'));
const initialOpenPressures = initialState.tensions.filter((tension) => tension.state === 'open').length;

class ClassList {
  constructor(element) { this.element = element; this.values = new Set(); }
  add(...names) { names.forEach((name) => this.values.add(name)); }
  remove(...names) { names.forEach((name) => this.values.delete(name)); }
  contains(name) { return this.values.has(name); }
  toggle(name, force) {
    const add = force === undefined ? !this.values.has(name) : force;
    if (add) this.values.add(name); else this.values.delete(name);
    return add;
  }
  get value() { return Array.from(this.values).join(' '); }
}

class Style {
  setProperty(key, value) { this[key] = value; }
}

class Element {
  constructor(tagName, namespace) {
    this.tagName = String(tagName);
    this.namespaceURI = namespace || null;
    this.children = [];
    this.parentNode = null;
    this.attributes = {};
    this.classList = new ClassList(this);
    this.style = new Style();
    this.dataset = {};
    this.listeners = {};
    this._text = '';
    this._id = '';
    this.value = '';
    this.open = false;
    this.hidden = false;
    this.disabled = false;
    this.title = '';
    this.scrollTop = 0;
    this.files = null;
  }
  get id() { return this._id; }
  set id(value) { this._id = String(value); if (global.document) global.document.byId.set(this._id, this); }
  get className() { return this.classList.value; }
  set className(value) { this.classList.values = new Set(String(value).split(/\s+/).filter(Boolean)); }
  get textContent() {
    return this._text + this.children.map((child) => child.textContent).join('');
  }
  set textContent(value) {
    this.children = [];
    this._text = String(value == null ? '' : value);
  }
  get firstChild() { return this.children[0] || null; }
  get offsetWidth() { return 100; }
  appendChild(child) {
    if (child instanceof DocumentFragment) {
      child.children.slice().forEach((inner) => this.appendChild(inner));
      child.children = [];
      return child;
    }
    if (child.parentNode) child.parentNode.removeChild(child);
    child.parentNode = this;
    this.children.push(child);
    return child;
  }
  removeChild(child) {
    const index = this.children.indexOf(child);
    if (index !== -1) this.children.splice(index, 1);
    child.parentNode = null;
    return child;
  }
  setAttribute(name, value) {
    this.attributes[name] = String(value);
    if (name === 'class') this.className = value;
    if (name === 'id') this.id = value;
  }
  getAttribute(name) { return this.attributes[name] === undefined ? null : this.attributes[name]; }
  removeAttribute(name) { delete this.attributes[name]; }
  addEventListener(type, listener) {
    (this.listeners[type] || (this.listeners[type] = [])).push(listener);
  }
  dispatchEvent(event) {
    event.target = event.target || this;
    event.currentTarget = this;
    (this.listeners[event.type] || []).forEach((listener) => listener(event));
    return true;
  }
  click() { this.dispatchEvent({ type: 'click', preventDefault() {} }); }
  focus() {}
  select() {}
  setSelectionRange() {}
  showModal() { this.open = true; this.setAttribute('open', ''); }
  close() { this.open = false; this.removeAttribute('open'); }
  querySelectorAll(selector) {
    const found = [];
    const visit = (node) => {
      node.children.forEach((child) => {
        if (matches(child, selector)) found.push(child);
        visit(child);
      });
    };
    visit(this);
    return found;
  }
  querySelector(selector) { return this.querySelectorAll(selector)[0] || null; }
}

class DocumentFragment {
  constructor() { this.children = []; }
  appendChild(child) { this.children.push(child); child.parentNode = null; return child; }
}

function matches(element, selector) {
  if (selector.startsWith('.')) return element.classList.contains(selector.slice(1));
  if (selector.startsWith('#')) return element.id === selector.slice(1);
  const attrOnly = selector.match(/^\[([^\]]+)\]$/);
  if (attrOnly) return element.getAttribute(attrOnly[1]) !== null;
  const tagAttr = selector.match(/^([a-z]+)\[([^\]]+)\]$/i);
  if (tagAttr) {
    return element.tagName.toLowerCase() === tagAttr[1].toLowerCase() && element.getAttribute(tagAttr[2]) !== null;
  }
  return element.tagName.toLowerCase() === selector.toLowerCase();
}

class Document {
  constructor() {
    this.byId = new Map();
    this.body = new Element('body');
    this.readyState = 'complete';
    this.listeners = {};
    this.body.parentNode = this;
  }
  createElement(tag) { return new Element(tag); }
  createElementNS(namespace, tag) { return new Element(tag, namespace); }
  createDocumentFragment() { return new DocumentFragment(); }
  getElementById(id) { return this.byId.get(id) || null; }
  querySelectorAll(selector) { return this.body.querySelectorAll(selector); }
  querySelector(selector) { return this.querySelectorAll(selector)[0] || null; }
  addEventListener(type, listener) { (this.listeners[type] || (this.listeners[type] = [])).push(listener); }
}

const document = new Document();
