'use strict';

/*
 * Dependency-free engine checks.
 * Run with: node test/engine.test.js
 * In a Codex-like sandbox without node, ELECTRON_RUN_AS_NODE can supply it.
 */
const assert = require('assert');
const fs = require('fs');
const path = require('path');

global.window = global;
require('../assets/engine.js');

const E = window.TendoraEngine;
const root = path.resolve(__dirname, '..');
let checks = 0;

function check(name, fn) {
  fn();
  checks += 1;
  process.stdout.write('  ok  ' + name + '\n');
}

check('seed world is valid and chained', () => {
  const world = E.createLocalWorld('2026-10-21T19:30:00.000Z');
  const result = E.validateWorld(world);
  assert.deepStrictEqual(result.errors, []);
  assert.strictEqual(world.revision, 2);
  assert.strictEqual(world.receipts[0].prev, E.ZERO);
  assert.strictEqual(world.receipts[1].prev, world.receipts[0].fingerprint);
  assert.match(world.receipts[0].fingerprint, /^[0-9a-f]{16}$/);
});

check('all five hands append a valid receipt', () => {
  let world = E.createLocalWorld('2026-10-21T19:30:00.000Z');
  const inputs = {
    probe: 'What did the hand forget when the portal answered quickly?',
    chisel: 'Leave the seam visible where the next hand can find it.',
    beam: 'The world must keep a way to revise its own laws.',
    boundary: 'No gesture leaves this workbench without a question still open.',
    rehearsal: 'Let the next mind arrive after this one has forgotten why.'
  };
  E.TOOL_KINDS.forEach((kind, index) => {
    const previousRevision = world.revision;
    const at = `2026-10-21T19:3${index + 1}:00.000Z`;
    const result = E.applyGesture(world, kind, inputs[kind], at);
    world = result.world;
    assert.strictEqual(result.receipt.kind, kind);
    assert.strictEqual(result.receipt.seq, previousRevision);
    assert.strictEqual(world.revision, previousRevision + 1);
    assert.deepStrictEqual(E.validateWorld(world).errors, []);
  });
  assert.strictEqual(world.receipts.length, 7);
  assert.ok(world.tensions.length >= 5);
});

check('a gesture without keywords still reads as a sentence', () => {
  let world = E.createLocalWorld('2026-10-21T19:30:00.000Z');
  const result = E.applyGesture(world, 'probe', 'to be or not', '2026-10-21T19:31:00.000Z');
  assert(!/the the/i.test(result.receipt.response), 'fallback article doubled');
  assert(!/the the/i.test(result.receipt.pressure || ''), 'fallback pressure article doubled');
  assert.strictEqual(E.analyze('to be or not', 'probe', 2).primary, 'unspoken');
});

check('tampering with a receipt is detected', () => {
  let world = E.createLocalWorld('2026-10-21T19:30:00.000Z');
  world = E.applyGesture(world, 'probe', 'What remains unspoken in the material?', '2026-10-21T19:31:00.000Z').world;
  world.receipts[2].text = 'A different story.';
  const result = E.validateWorld(world);
  assert.strictEqual(result.ok, false);
  assert.ok(result.errors.some((message) => message.includes('fingerprint')));
});

check('short and unknown gestures are refused', () => {
  const world = E.createLocalWorld('2026-10-21T19:30:00.000Z');
  assert.throws(() => E.applyGesture(world, 'probe', 'tiny', '2026-10-21T19:31:00.000Z'), /at least a sentence/);
  assert.throws(() => E.applyGesture(world, 'portal', 'A gesture that uses the wrong tool.', '2026-10-21T19:31:00.000Z'), /Unknown tool/);
});

check('committed seed and state validate and share a prefix', () => {
  const seed = JSON.parse(fs.readFileSync(path.join(root, 'world', 'seed.json'), 'utf8'));
  const state = JSON.parse(fs.readFileSync(path.join(root, 'world', 'state.json'), 'utf8'));
  assert.deepStrictEqual(E.validateWorld(seed).errors, []);
  assert.deepStrictEqual(E.validateWorld(state).errors, []);
  assert.ok(state.receipts.length > seed.receipts.length);
  assert.deepStrictEqual(state.receipts.slice(0, seed.receipts.length), seed.receipts);
  assert.strictEqual(state.title, seed.title);
  assert.strictEqual(state.inheritance.sha256, seed.inheritance.sha256);
});

check('handoff carries the open pressures and provenance', () => {
  const state = JSON.parse(fs.readFileSync(path.join(root, 'world', 'state.json'), 'utf8'));
  const handoff = E.generateHandoff(state);
  const open = E.openTensions(state);
  assert.ok(handoff.startsWith('# A door left open'));
  assert.ok(handoff.includes(state.title));
  assert.ok(handoff.includes(state.receipts[state.receipts.length - 1].fingerprint));
  open.forEach((tension) => assert.ok(handoff.includes(tension.text), 'missing pressure: ' + tension.text));
  assert.ok(handoff.includes('world/state.json'));
  assert.ok(handoff.includes('CONTINUE.md'));
});

check('weather and pulse are deterministic descriptors', () => {
  const state = JSON.parse(fs.readFileSync(path.join(root, 'world', 'state.json'), 'utf8'));
  assert.strictEqual(typeof E.weatherFor(state), 'string');
  assert.ok(E.weatherFor(state).length > 4);
  assert.ok(['form', 'weather', 'care', 'resistance'].includes(E.pulseWord(state)));
});

process.stdout.write(`\n${checks} engine checks passed.\n`);

#!/usr/bin/env node
/*
 * Place one gesture into a Tendora world without opening the browser.
 * The same engine and receipt chain are used as the workbench UI.
 *
 *   node tools/place.js --tool=probe --text="Ask what the material remembers."
 *
 * Options:
 *   --tool, -t   probe | chisel | beam | boundary | rehearsal
 *   --text, -m   the gesture (8–600 characters)
 *   --state, -s  default: world/state.json
 *   --at         optional ISO timestamp (useful for deterministic tests)
 *   --dry-run    print the answer without writing
 *   --embed      refresh assets/inherited-state.js even for a custom --state
 *   --no-embed   do not refresh assets/inherited-state.js
 */
'use strict';

const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
global.window = global;
require(path.join(root, 'assets/engine.js'));
const E = window.TendoraEngine;

const options = {
  tool: null,
  text: null,
  state: path.join(root, 'world/state.json'),
  at: null,
  dryRun: false,
  embed: null,
  explicitState: false
};

function fail(message, code) {
  process.stderr.write('tendora: ' + message + '\n');
  process.exit(code || 1);
}

function takeValue(index) {
  if (index + 1 >= process.argv.length) {
    fail('Missing value after ' + process.argv[index]);
  }
  return process.argv[index + 1];
}

for (let index = 2; index < process.argv.length; index += 1) {
  const argument = process.argv[index];
  if (argument === '--help' || argument === '-h') {
    process.stdout.write('Usage: node tools/place.js --tool=probe --text="A gesture." [--state=world/state.json] [--dry-run] [--no-embed]\n');
    process.exit(0);
  } else if (argument === '--tool' || argument === '-t') {
    options.tool = takeValue(index); index += 1;
  } else if (argument.startsWith('--tool=')) {
    options.tool = argument.split('=', 2)[1];
  } else if (argument === '--text' || argument === '-m') {
    options.text = takeValue(index); index += 1;
  } else if (argument.startsWith('--text=')) {
    options.text = argument.split('=', 2)[1];
  } else if (argument === '--state' || argument === '-s') {
    options.state = path.resolve(process.cwd(), takeValue(index)); options.explicitState = true; index += 1;
  } else if (argument.startsWith('--state=')) {
    options.state = path.resolve(process.cwd(), argument.split('=', 2)[1]); options.explicitState = true;
  } else if (argument === '--at') {
    options.at = takeValue(index); index += 1;
  } else if (argument.startsWith('--at=')) {
    options.at = argument.split('=', 2)[1];
  } else if (argument === '--dry-run') {
    options.dryRun = true;
  } else if (argument === '--embed') {
    options.embed = true;
  } else if (argument === '--no-embed') {
    options.embed = false;
  } else {
    fail('Unknown argument: ' + argument);
  }
}

if (!options.tool) {
  fail('Choose a hand with --tool=probe|chisel|beam|boundary|rehearsal.');
}
if (!options.text) {
  fail('A gesture needs --text="…".');
}
if (options.at && isNaN(Date.parse(options.at))) {
  fail('--at must be a valid ISO timestamp.');
}

let sourcePath = options.state;
if (!fs.existsSync(sourcePath)) {
  if (options.explicitState) {
    fail('No world at ' + sourcePath);
  }
  sourcePath = path.join(root, 'world/seed.json');
}
let source;
try {
  source = JSON.parse(fs.readFileSync(sourcePath, 'utf8'));
} catch (error) {
  fail('Could not read ' + sourcePath + ': ' + error.message);
}
const validatedSource = E.validateWorld(source);
if (!validatedSource.ok) {
  fail('The world is invalid: ' + validatedSource.errors[0]);
}

let result;
try {
  result = E.applyGesture(source, options.tool, options.text, options.at || new Date().toISOString());
} catch (error) {
  fail(error.message);
}
const world = result.world;
const validated = E.validateWorld(world);
if (!validated.ok) {
  fail('The gesture produced an invalid world: ' + validated.errors[0]);
}

function wrap(text, width, indent) {
  const words = String(text).split(/\s+/);
  const lines = [];
  let line = '';
  words.forEach((word) => {
    if ((line + ' ' + word).trim().length > width) {
      lines.push(line.trim());
      line = word;
    } else {
      line += ' ' + word;
    }
  });
  if (line.trim()) lines.push(line.trim());
  return lines.join('\n' + indent);
}

let shouldEmbed = false;
if (!options.dryRun) {
  fs.mkdirSync(path.dirname(options.state), { recursive: true });
  const temporary = options.state + '.tmp-' + process.pid;
  try {
    fs.writeFileSync(temporary, JSON.stringify(world, null, 2) + '\n', 'utf8');
    fs.renameSync(temporary, options.state);
  } finally {
    if (fs.existsSync(temporary)) fs.unlinkSync(temporary);
  }
  const canonicalState = path.join(root, 'world/state.json');
  shouldEmbed = options.embed === null ? options.state === canonicalState : options.embed;
  if (shouldEmbed) {
    const header = '/*\n * Generated from world/state.json by the Tendora tooling.\n * This is the static snapshot for opening index.html without a server.\n * The living state on disk always wins when the workbench API is available.\n */\n';
    fs.writeFileSync(path.join(root, 'assets/inherited-state.js'),
      header + 'window.TENDORA_INHERITED_STATE = ' + JSON.stringify(world, null, 2) + ';\n', 'utf8');
  }
}

process.stdout.write('TENDORA · gesture placed' + (options.dryRun ? ' (dry run)' : '') + '\n\n');
process.stdout.write('  hand        ' + options.tool + '\n');
process.stdout.write('  receipt     #' + String(result.receipt.seq).padStart(2, '0') + '\n');
process.stdout.write('  revision    ' + String(world.revision).padStart(2, '0') + '\n');
process.stdout.write('  fingerprint ' + result.receipt.fingerprint + '\n');
process.stdout.write('\n  the world answers\n    ' + wrap(result.receipt.response, 72, '    ') + '\n');
if (result.receipt.pressure) {
  process.stdout.write('\n  what it resists\n    ' + wrap(result.receipt.pressure, 72, '    ') + '\n');
}
process.stdout.write('\n  ' + (options.dryRun ? 'nothing written' : 'written to ' + options.state) + '\n');
if (!options.dryRun) {
  process.stdout.write('  ' + (shouldEmbed ? 'static snapshot refreshed' : 'static snapshot left alone') + '\n');
}
process.stdout.write('\nLeave a door open before you go.\n');
